// ZALU Design System Builder (Figma plugin, owner: Damir)
// Builds in the open file: token variables + text styles, core components with variants, Foundations,
// and three top-level stages with linked detail screens for footage, labels and evaluation.
// Mirrors frontend/src (same token names, same copy). Re-running replaces what the plugin created earlier.
// Works on the Starter plan (3 pages). Run: Figma desktop -> Plugins -> Development -> Import plugin from manifest.

// <TOKENS> generated by design/sync_tokens.py from frontend/src/app/globals.css — do not edit by hand
const TOKENS = {
  "color": {
    "bg": "#F7F9FC",
    "surface": "#FFFFFF",
    "surface-2": "#EEF2F7",
    "ink": "#172033",
    "ink-2": "#475467",
    "muted": "#5A6478",
    "line": "#E3E8F0",
    "control": "#7D879A",
    "brand": "#315CFD",
    "brand-hover": "#2447D8",
    "brand-soft": "#EAF0FF",
    "brand-ink": "#2447D8",
    "success": "#147D64",
    "success-soft": "#E7F5F0",
    "success-ink": "#0F6B55",
    "warning": "#B46D12",
    "warning-soft": "#FDF3E3",
    "warning-ink": "#8A5208",
    "error": "#C43D4B",
    "error-soft": "#FBEAEC",
    "error-ink": "#A3303D",
    "sample": "#6D3FD9",
    "sample-soft": "#F2EDFE",
    "tp": "#147D64",
    "fp": "#C43D4B",
    "fn": "#B46D12"
  },
  "radius": {
    "sm": 6,
    "md": 8,
    "lg": 12
  }
};
// </TOKENS>

const PREFIX = "ZALU · ";
const COLLECTION = "ZALU / Tokens";
const SPACING = [4, 8, 12, 16, 24, 32, 48];
const TEXT_STYLES = [
  ["Heading/H1", "Semi Bold", 28, 125, -1], ["Heading/H2", "Semi Bold", 22, 125, -1], ["Heading/H3", "Semi Bold", 17, 130, 0],
  ["Body/Default", "Regular", 15, 150, 0], ["Body/Strong", "Semi Bold", 15, 150, 0], ["Body/Small", "Regular", 13, 150, 0],
  ["Body/Small Strong", "Semi Bold", 13, 150, 0], ["Caption", "Regular", 12, 150, 0], ["Label", "Semi Bold", 12, 150, 0],
  ["Metric/KPI", "Bold", 28, 120, -2], ["Mono/Caption", "Regular", 12, 150, 0],
];
const SCOPES = (name) =>
  /ink|muted/.test(name) ? ["TEXT_FILL"] :
  /^(line|control)$/.test(name) ? ["STROKE_COLOR"] :
  /^(tp|fp|fn)$/.test(name) ? ["STROKE_COLOR"] :
  ["FRAME_FILL", "SHAPE_FILL", "STROKE_COLOR", "TEXT_FILL"];

const V = {};   // variable name -> Variable
const S = {};   // text style name -> TextStyle
const C = {};   // component name -> ComponentSetNode | ComponentNode

// ---------------------------------------------------------------- helpers
const rgb = (h) => ({ r: parseInt(h.slice(1, 3), 16) / 255, g: parseInt(h.slice(3, 5), 16) / 255, b: parseInt(h.slice(5, 7), 16) / 255 });
const paint = (name) => figma.variables.setBoundVariableForPaint({ type: "SOLID", color: { r: 0, g: 0, b: 0 } }, "color", V["color/" + name]);
function fill(node, name) { node.fills = name ? [paint(name)] : []; return node; }
function stroke(node, name, w = 1, dash) { node.strokes = [paint(name)]; node.strokeWeight = w; node.strokeAlign = "INSIDE"; if (dash) node.dashPattern = dash; return node; }
function radius(node, key) {
  const v = V["radius/" + key];
  if (!v) { node.cornerRadius = key === "full" ? 999 : 0; return node; }
  for (const c of ["topLeftRadius", "topRightRadius", "bottomLeftRadius", "bottomRightRadius"]) node.setBoundVariable(c, v);
  return node;
}
function spacing(node, prop, n) { const v = V["spacing/" + n]; if (v) node.setBoundVariable(prop, v); else node[prop] = n; }

/** Auto-layout frame. pad = [top, right, bottom, left]; w = fixed width (else hug). */
function box(name, dir = "VERTICAL", o = {}) {
  const f = figma.createFrame();
  f.name = name;
  f.layoutMode = dir;
  f.fills = [];
  f.clipsContent = false;
  if (o.w || o.h) f.resize(o.w || 100, o.h || 10);
  f.primaryAxisSizingMode = o.h && dir === "VERTICAL" ? "FIXED" : (o.w && dir === "HORIZONTAL" ? "FIXED" : "AUTO");
  f.counterAxisSizingMode = (o.w && dir === "VERTICAL") || (o.h && dir === "HORIZONTAL") ? "FIXED" : "AUTO";
  if (o.gap != null) spacing(f, "itemSpacing", o.gap);
  if (o.pad) { const [t, r, b, l] = o.pad; spacing(f, "paddingTop", t); spacing(f, "paddingRight", r); spacing(f, "paddingBottom", b); spacing(f, "paddingLeft", l); }
  if (o.fill) fill(f, o.fill);
  if (o.stroke) stroke(f, o.stroke, 1, o.dash);
  if (o.radius) radius(f, o.radius);
  f.primaryAxisAlignItems = o.main || "MIN";
  f.counterAxisAlignItems = o.cross || "MIN";
  return f;
}
/** Append child; optionally make it fill the parent's width/height. */
function add(parent, child, o = {}) {
  parent.appendChild(child);
  if (o.fillW) child.layoutSizingHorizontal = "FILL";
  if (o.fillH) child.layoutSizingVertical = "FILL";
  if (o.grow) child.layoutGrow = 1;
  return child;
}
async function text(str, style = "Body/Default", color = "ink", o = {}) {
  const t = figma.createText();
  t.fontName = { family: "Inter", style: "Regular" };
  t.characters = str;
  await t.setTextStyleIdAsync(S[style].id);
  fill(t, color);
  t.name = o.name || str.slice(0, 40);
  return t;
}
async function addText(parent, str, style, color, o = {}) {
  const t = await text(str, style, color, o);
  parent.appendChild(t);
  if (o.wrap) { t.layoutSizingHorizontal = "FILL"; t.textAutoResize = "HEIGHT"; }
  return t;
}
function rect(name, w, h, color) { const r = figma.createRectangle(); r.name = name; r.resize(w, h); fill(r, color); return r; }
function spacer(parent) { const s = box("Spacer", "HORIZONTAL"); add(parent, s, { grow: true }); return s; }

/** Instance of a variant ("Style=Primary, State=Default") with text props {Label: "..."}. */
function inst(compName, variant, props = {}) {
  const c = C[compName];
  const main = c.type === "COMPONENT_SET" ? (c.children.find((v) => v.name === variant) || c.defaultVariant) : c;
  const i = main.createInstance();
  const defs = i.componentProperties;
  const set = {};
  for (const [k, v] of Object.entries(props)) {
    const key = Object.keys(defs).find((d) => d.split("#")[0] === k);
    if (key) set[key] = v;
  }
  if (Object.keys(set).length) i.setProperties(set);
  return i;
}

/** Build a component set from variants. build(values) returns a ComponentNode; textProps: {Prop: default} bound by node name. */
async function componentSet(name, axes, build, textProps, page, x, y, desc) {
  const combos = axes.reduce((acc, [k, vals]) => acc.flatMap((a) => vals.map((v) => ({ ...a, [k]: v }))), [{}]);
  const comps = [];
  for (const values of combos) {
    const comp = await build(values);
    comp.name = Object.entries(values).map(([k, v]) => `${k}=${v}`).join(", ");
    page.appendChild(comp);
    comps.push(comp);
  }
  const set = figma.combineAsVariants(comps, page);
  set.name = name;
  if (desc) set.description = desc;
  for (const [prop, def] of Object.entries(textProps || {})) {
    const key = set.addComponentProperty(prop, "TEXT", def);
    for (const v of set.children) {
      const t = v.findOne((n) => n.type === "TEXT" && n.name === prop);
      if (t) t.componentPropertyReferences = { characters: key };
    }
  }
  // grid layout of variants (they stack at 0,0 after combine)
  const cols = axes.length > 1 ? axes[axes.length - 1][1].length : Math.min(combos.length, 5);
  let maxW = 0, maxH = 0;
  for (const v of set.children) { maxW = Math.max(maxW, v.width); maxH = Math.max(maxH, v.height); }
  set.children.forEach((v, i) => { v.x = 24 + (i % cols) * (maxW + 24); v.y = 24 + Math.floor(i / cols) * (maxH + 24); });
  set.resizeWithoutConstraints(24 + cols * (maxW + 24), 24 + Math.ceil(set.children.length / cols) * (maxH + 24));
  fill(set, "surface");
  stroke(set, "sample", 1, [6, 4]);
  set.x = x; set.y = y;
  C[name] = set;
  return set;
}

// ---------------------------------------------------------------- foundations
async function foundations() {
  await Promise.all(["Regular", "Semi Bold", "Bold"].map((style) => figma.loadFontAsync({ family: "Inter", style })));

  const cols = await figma.variables.getLocalVariableCollectionsAsync();
  let col = cols.find((c) => c.name === COLLECTION);
  if (!col) { col = figma.variables.createVariableCollection(COLLECTION); col.renameMode(col.modes[0].modeId, "Light"); }
  const mode = col.modes[0].modeId;
  const existing = (await figma.variables.getLocalVariablesAsync()).filter((v) => v.variableCollectionId === col.id);
  const upsert = (name, type) => existing.find((v) => v.name === name) || figma.variables.createVariable(name, col, type);

  for (const [k, hex] of Object.entries(TOKENS.color)) {
    const v = upsert("color/" + k, "COLOR");
    v.setValueForMode(mode, rgb(hex)); v.scopes = SCOPES(k); v.setVariableCodeSyntax("WEB", `var(--color-${k})`);
    V["color/" + k] = v;
  }
  const white = upsert("color/on-brand", "COLOR");
  white.setValueForMode(mode, rgb("#FFFFFF")); white.scopes = ["TEXT_FILL", "SHAPE_FILL"]; white.setVariableCodeSyntax("WEB", "#fff");
  V["color/on-brand"] = white;
  const stage = upsert("color/stage", "COLOR");
  stage.setValueForMode(mode, rgb("#0E1422")); stage.scopes = ["FRAME_FILL", "SHAPE_FILL"]; stage.setVariableCodeSyntax("WEB", "#0E1422");
  V["color/stage"] = stage;
  for (const n of SPACING) {
    const v = upsert("spacing/" + n, "FLOAT");
    v.setValueForMode(mode, n); v.scopes = ["GAP"]; v.setVariableCodeSyntax("WEB", `${n}px`);
    V["spacing/" + n] = v;
  }
  for (const [k, n] of Object.entries(TOKENS.radius)) {
    const v = upsert("radius/" + k, "FLOAT");
    v.setValueForMode(mode, n); v.scopes = ["CORNER_RADIUS"]; v.setVariableCodeSyntax("WEB", `var(--radius-${k})`);
    V["radius/" + k] = v;
  }

  const styles = await figma.getLocalTextStylesAsync();
  for (const [name, style, size, lh, ls] of TEXT_STYLES) {
    const s = styles.find((x) => x.name === name) || figma.createTextStyle();
    s.name = name;
    s.fontName = { family: "Inter", style };
    s.fontSize = size;
    s.lineHeight = { unit: "PERCENT", value: lh };
    s.letterSpacing = { unit: "PERCENT", value: ls };
    S[name] = s;
  }
}

// ---------------------------------------------------------------- components
const TONE = {
  Sample: ["sample-soft", "sample", "◆"], Success: ["success-soft", "success-ink", "✓"], Warning: ["warning-soft", "warning-ink", "!"],
  Error: ["error-soft", "error-ink", "✕"], Info: ["brand-soft", "brand-ink", "i"],
};

async function components(page) {
  let y = 160;
  const title = await text("Components", "Heading/H1", "ink");
  page.appendChild(title); title.x = 0; title.y = 0;
  const sub = await text("Every component mirrors a class in frontend/src/app/globals.css. Status is always icon + text, never colour alone.", "Body/Default", "ink-2");
  page.appendChild(sub); sub.x = 0; sub.y = 48;

  const row = async (set, label) => {
    const l = await text(label, "Heading/H3", "ink");
    page.appendChild(l); l.x = 0; l.y = y - 32;
    set.x = 0; set.y = y; y += set.height + 96;
  };

  // Button
  await row(await componentSet("Button", [["Style", ["Primary", "Secondary", "Ghost", "Danger"]], ["State", ["Default", "Disabled"]]], async (v) => {
    const c = figma.createComponent();
    c.layoutMode = "HORIZONTAL"; c.resize(120, 40); c.primaryAxisSizingMode = "AUTO"; c.counterAxisSizingMode = "FIXED"; // resize() resets sizing to FIXED, so it goes first
    c.primaryAxisAlignItems = "CENTER"; c.counterAxisAlignItems = "CENTER";
    spacing(c, "paddingLeft", 16); spacing(c, "paddingRight", 16); spacing(c, "itemSpacing", 8); radius(c, "md");
    const primary = v.Style === "Primary";
    fill(c, primary ? "brand" : v.Style === "Ghost" ? null : "surface");
    if (v.Style === "Secondary" || v.Style === "Danger") stroke(c, "line");
    const t = await text("Button", "Body/Small Strong", primary ? "on-brand" : v.Style === "Danger" ? "error-ink" : "ink", { name: "Label" });
    c.appendChild(t);
    if (v.State === "Disabled") c.opacity = 0.5;
    return c;
  }, { Label: "Button" }, page, 0, 0, "One primary action per screen. Min height 40 px. Disabled = 50% opacity + not focusable."), "Button");

  // Badge
  await row(await componentSet("Badge", [["Tone", Object.keys(TONE)]], async (v) => {
    const [bg, fg, ic] = TONE[v.Tone];
    const c = figma.createComponent();
    c.layoutMode = "HORIZONTAL"; c.primaryAxisSizingMode = "AUTO"; c.counterAxisSizingMode = "AUTO";
    c.counterAxisAlignItems = "CENTER";
    spacing(c, "paddingLeft", 8); spacing(c, "paddingRight", 8); spacing(c, "paddingTop", 4); spacing(c, "paddingBottom", 4); spacing(c, "itemSpacing", 4);
    radius(c, "sm"); fill(c, bg);
    c.appendChild(await text(ic, "Label", fg, { name: "Icon" }));
    c.appendChild(await text(v.Tone === "Sample" ? "Sample data" : v.Tone, "Label", fg, { name: "Label" }));
    return c;
  }, { Label: "Label" }, page, 0, 0, "Status label. The icon carries meaning for colour-blind users."), "Badge");

  // Banner
  await row(await componentSet("Banner", [["Tone", Object.keys(TONE)]], async (v) => {
    const [bg, fg, ic] = TONE[v.Tone];
    const c = figma.createComponent();
    c.layoutMode = "HORIZONTAL"; c.resize(520, 10); c.primaryAxisSizingMode = "FIXED"; c.counterAxisSizingMode = "AUTO";
    spacing(c, "paddingLeft", 16); spacing(c, "paddingRight", 16); spacing(c, "paddingTop", 12); spacing(c, "paddingBottom", 12); spacing(c, "itemSpacing", 12);
    radius(c, "md"); fill(c, bg);
    c.appendChild(await text(ic, "Body/Small Strong", fg, { name: "Icon" }));
    const body = box("Content", "VERTICAL", { gap: 4 });
    add(c, body, { grow: true });
    body.layoutSizingHorizontal = "FILL";
    await addText(body, "Title", "Body/Small Strong", fg, { name: "Title", wrap: true });
    await addText(body, "Supporting text explains what happened and what to do next.", "Body/Small", fg, { name: "Body", wrap: true });
    return c;
  }, { Title: "Title", Body: "Supporting text explains what happened and what to do next." }, page, 0, 0, "Inline system feedback. Error tone = role=alert in code."), "Banner");

  // Step
  await row(await componentSet("Step", [["State", ["Active", "Done", "Available", "Locked"]]], async (v) => {
    const c = figma.createComponent();
    c.layoutMode = "HORIZONTAL"; c.resize(184, 52); c.primaryAxisSizingMode = "FIXED"; c.counterAxisSizingMode = "FIXED";
    c.counterAxisAlignItems = "CENTER";
    spacing(c, "paddingLeft", 12); spacing(c, "paddingRight", 12); spacing(c, "itemSpacing", 8);
    radius(c, "lg");
    fill(c, v.State === "Active" ? "brand-soft" : "surface"); stroke(c, v.State === "Active" ? "brand" : "line");
    const num = box("Number badge", "HORIZONTAL", { main: "CENTER", cross: "CENTER" });
    num.resize(24, 24); num.primaryAxisSizingMode = "FIXED"; num.counterAxisSizingMode = "FIXED"; num.cornerRadius = 12;
    fill(num, v.State === "Active" ? "brand" : v.State === "Done" ? "success" : "surface-2");
    num.appendChild(await text(v.State === "Done" ? "✓" : "1", "Label", v.State === "Active" || v.State === "Done" ? "on-brand" : "ink-2", { name: "Number" }));
    c.appendChild(num);
    const col = box("Text", "VERTICAL");
    c.appendChild(col);
    col.appendChild(await text("Describe", "Body/Small Strong", v.State === "Locked" ? "muted" : "ink", { name: "Step" }));
    col.appendChild(await text("What to detect", "Caption", "muted", { name: "Hint" }));
    return c;
  }, { Number: "1", Step: "Describe", Hint: "What to detect" }, page, 0, 0, "Stepper item. Locked steps are disabled buttons; current step has aria-current=step."), "Step");

  // Verdict
  const VER = { "Ready": ["success-soft", "success", "success-ink", "✓", "Ready to deploy"], "Not ready": ["error-soft", "error", "error-ink", "✕", "Not ready yet"],
    "Insufficient data": ["warning-soft", "warning", "warning-ink", "!", "Promising, but not proven"], "Invalid test": ["error-soft", "ink", "error-ink", "⚠", "Test invalid: data leakage"] };
  await row(await componentSet("Verdict", [["Verdict", Object.keys(VER)]], async (v) => {
    const [bg, iconBg, fg, ic, label] = VER[v.Verdict];
    const c = figma.createComponent();
    c.layoutMode = "HORIZONTAL"; c.resize(560, 10); c.primaryAxisSizingMode = "FIXED"; c.counterAxisSizingMode = "AUTO";
    c.counterAxisAlignItems = "CENTER";
    spacing(c, "paddingLeft", 16); spacing(c, "paddingRight", 16); spacing(c, "paddingTop", 16); spacing(c, "paddingBottom", 16); spacing(c, "itemSpacing", 16);
    radius(c, "lg"); fill(c, bg);
    const icon = box("Icon", "HORIZONTAL", { main: "CENTER", cross: "CENTER" });
    icon.resize(40, 40); icon.primaryAxisSizingMode = "FIXED"; icon.counterAxisSizingMode = "FIXED"; radius(icon, "md"); fill(icon, iconBg);
    icon.appendChild(await text(ic, "Heading/H3", "on-brand"));
    c.appendChild(icon);
    const col = box("Text", "VERTICAL", { gap: 4 });
    add(c, col, { grow: true }); col.layoutSizingHorizontal = "FILL";
    await addText(col, label, "Body/Strong", fg, { name: "Verdict" });
    await addText(col, "Meets all acceptance criteria on independent test footage. A small test set never proves production safety.", "Body/Small", fg, { name: "Summary", wrap: true });
    return c;
  }, { Summary: "Meets all acceptance criteria on independent test footage. A small test set never proves production safety." }, page, 0, 0,
  "Deployment readiness against explicit acceptance criteria (backend/evaluation_engine/core.py readiness())."), "Verdict");

  // Chip
  await row(await componentSet("Chip", [["Tone", ["Default", "Accent", "Negative"]]], async (v) => {
    const c = figma.createComponent();
    c.layoutMode = "HORIZONTAL"; c.resize(80, 32); c.primaryAxisSizingMode = "AUTO"; c.counterAxisSizingMode = "FIXED";
    c.counterAxisAlignItems = "CENTER"; c.cornerRadius = 999;
    spacing(c, "paddingLeft", 12); spacing(c, "paddingRight", 12); spacing(c, "itemSpacing", 4);
    fill(c, v.Tone === "Accent" ? "brand-soft" : v.Tone === "Negative" ? "warning-soft" : "surface"); stroke(c, "line");
    c.appendChild(await text("chip", "Body/Small", v.Tone === "Accent" ? "brand-ink" : v.Tone === "Negative" ? "warning-ink" : "ink", { name: "Label" }));
    return c;
  }, { Label: "chip" }, page, 0, 0, "Classes (accent), look-alikes (negative) and example prompts (default)."), "Chip");

  // KPI tile (single component)
  const k = figma.createComponent();
  k.name = "KPI";
  k.layoutMode = "VERTICAL"; k.resize(220, 10); k.primaryAxisSizingMode = "AUTO"; k.counterAxisSizingMode = "FIXED";
  spacing(k, "paddingLeft", 16); spacing(k, "paddingRight", 16); spacing(k, "paddingTop", 12); spacing(k, "paddingBottom", 12); spacing(k, "itemSpacing", 4);
  radius(k, "md"); fill(k, "surface-2");
  const kl = await addText(k, "Recall · objects found", "Label", "ink-2", { name: "Label", wrap: true });
  const kv = await addText(k, "90%", "Metric/KPI", "ink", { name: "Value" });
  const kr = await addText(k, "95% range 82%–95%", "Caption", "muted", { name: "Range", wrap: true });
  for (const [prop, node] of [["Label", kl], ["Value", kv], ["Range", kr]]) node.componentPropertyReferences = { characters: k.addComponentProperty(prop, "TEXT", node.characters) };
  k.description = "Headline metric with its 95% range. Never show a metric without its uncertainty.";
  page.appendChild(k);
  const kt = await text("KPI", "Heading/H3", "ink"); page.appendChild(kt); kt.x = 0; kt.y = y - 32;
  k.x = 0; k.y = y;
  C.KPI = k;
}

// ---------------------------------------------------------------- foundations page (cover + docs)
async function foundationsPage(page) {
  const root = box(PREFIX + "Cover & Foundations", "VERTICAL", { w: 1280, gap: 48, pad: [64, 64, 64, 64], fill: "bg" });
  page.appendChild(root);
  const cover = box("Cover", "VERTICAL", { gap: 16 });
  add(root, cover, { fillW: true });
  await addText(cover, "ZALU", "Heading/H1", "brand");
  await addText(cover, "Complex technology. Simple experience.", "Heading/H2", "ink");
  await addText(cover, "Build a custom camera model from one sentence, verify it honestly on new real footage, and run it locally. This file mirrors the working Next.js app: same tokens, components and copy. Sample data is always marked ◆.", "Body/Default", "ink-2", { wrap: true });

  const principles = box("Principles", "HORIZONTAL", { gap: 16 });
  add(root, principles, { fillW: true });
  for (const [t, d] of [["Simplicity", "One clear primary action per screen."], ["Clarity", "Plain language: “Recall · objects found”."], ["Trust", "Uncertainty and limits sit next to every result."], ["Accessibility", "WCAG 2.2 AA: text ≥ 4.5:1, controls ≥ 3:1, icon + text for status."]]) {
    const card = box(t, "VERTICAL", { gap: 8, pad: [16, 16, 16, 16], fill: "surface", stroke: "line", radius: "lg" });
    add(principles, card, { grow: true });
    await addText(card, t, "Body/Strong", "ink", { wrap: true });
    await addText(card, d, "Body/Small", "ink-2", { wrap: true });
  }

  await addText(root, "Colour", "Heading/H2", "ink");
  const grid = box("Swatches", "HORIZONTAL", { gap: 16 });
  grid.layoutWrap = "WRAP"; spacing(grid, "counterAxisSpacing", 16);
  add(root, grid, { fillW: true });
  for (const [k, hex] of Object.entries(TOKENS.color)) {
    const sw = box("color/" + k, "VERTICAL", { w: 132, gap: 8 });
    grid.appendChild(sw);
    const chip = rect("Swatch", 132, 64, k); chip.cornerRadius = 8; stroke(chip, "line");
    sw.appendChild(chip);
    await addText(sw, k, "Body/Small Strong", "ink");
    await addText(sw, hex, "Mono/Caption", "muted");
  }

  await addText(root, "Typography · Inter", "Heading/H2", "ink");
  const ramp = box("Type ramp", "VERTICAL", { gap: 12 });
  add(root, ramp, { fillW: true });
  for (const [name, , size] of TEXT_STYLES) await addText(ramp, `${name} · ${size}px · The quick brown fox detects goggles`, name, "ink");

  await addText(root, "Spacing (8 px grid) & radius", "Heading/H2", "ink");
  const sp = box("Spacing", "HORIZONTAL", { gap: 24, cross: "MAX" });
  add(root, sp, { fillW: true });
  for (const n of SPACING) {
    const c = box("spacing/" + n, "VERTICAL", { gap: 8, cross: "CENTER" });
    sp.appendChild(c);
    c.appendChild(rect("bar", n, n, "brand"));
    await addText(c, String(n), "Caption", "muted");
  }
  return root;
}

// ---------------------------------------------------------------- screens
const STAGES = ["Describe", "Train", "Deploy"];
const SCREENS = ["Describe", "Describe · Footage", "Describe · Labels", "Train", "Train · Evaluation", "Deploy"];
const STAGE_OF = [0, 0, 0, 1, 1, 2];
const PROGRESS = [1 / 3, 2 / 3, 1, 1 / 2, 1, 1];

async function shell(index, title, sub) {
  const f = box(`${PREFIX}${index + 1} ${SCREENS[index]}`, "VERTICAL", { w: 1280, gap: 24, pad: [16, 40, 48, 40], fill: "bg" });
  const top = box("Top bar", "HORIZONTAL", { gap: 16, cross: "CENTER" });
  add(f, top, { fillW: true });
  const mark = box("Brand mark", "HORIZONTAL", { main: "CENTER", cross: "CENTER" });
  mark.resize(32, 32); mark.primaryAxisSizingMode = "FIXED"; mark.counterAxisSizingMode = "FIXED"; radius(mark, "md"); fill(mark, "brand");
  const dot = figma.createEllipse(); dot.resize(10, 10); fill(dot, "on-brand"); mark.appendChild(dot);
  top.appendChild(mark);
  top.appendChild(await text("ZALU", "Body/Strong", "ink"));
  spacer(top);
  top.appendChild(inst("Badge", "Tone=Sample", { Label: "Sample mode" }));

  const stepper = box("Progress", "HORIZONTAL", { gap: 8 });
  add(f, stepper, { fillW: true });
  for (const [i, label] of STAGES.entries()) {
    const segment = box(label, "VERTICAL", { gap: 5 });
    add(stepper, segment, { grow: true });
    const track = rect("Track", 394, 4, "line");
    const bar = box("Progress stroke", "HORIZONTAL", { w: 394, h: 4 });
    bar.layoutMode = "NONE";
    bar.appendChild(track);
    const progress = i < STAGE_OF[index] ? 1 : i === STAGE_OF[index] ? PROGRESS[index] : 0;
    if (progress) bar.appendChild(rect("Completed", 394 * progress, 4, "brand"));
    segment.appendChild(bar);
    await addText(segment, label, "Body/Small Strong", i === STAGE_OF[index] ? "brand-ink" : "muted");
  }

  const head = box("Section head", "VERTICAL", { gap: 8, cross: "CENTER" });
  add(f, head, { fillW: true });
  await addText(head, title, "Heading/H1", "ink");
  await addText(head, sub, "Body/Default", "ink-2");
  return f;
}
function card(name, o = {}) { return box(name, "VERTICAL", { gap: o.gap ?? 16, pad: [24, 24, 24, 24], fill: "surface", stroke: "line", radius: "lg", ...o }); }
function cols(parent, side = 320) {
  const row = box("Columns", "HORIZONTAL", { gap: 24 });
  add(parent, row, { fillW: true });
  const main = box("Main", "VERTICAL", { gap: 16 }); add(row, main, { grow: true }); main.layoutSizingHorizontal = "FILL";
  const aside = box("Aside", "VERTICAL", { gap: 16, w: side }); row.appendChild(aside);
  return [main, aside];
}
function actions(parent, left, right) {
  const r = box("Actions", "HORIZONTAL", { gap: 12, cross: "CENTER" });
  add(parent, r, { fillW: true });
  for (const [label, style] of left) r.appendChild(inst("Button", `Style=${style}, State=Default`, { Label: label }));
  spacer(r);
  const btns = right.map(([label, style]) => { const b = inst("Button", `Style=${style}, State=Default`, { Label: label }); r.appendChild(b); return b; });
  return btns[btns.length - 1];
}
async function field(parent, label, value, o = {}) {
  const f = box(label, "VERTICAL", { gap: 4 }); add(parent, f, { fillW: true });
  await addText(f, label, "Label", "ink-2");
  const input = box("Input", "HORIZONTAL", { pad: [8, 12, 8, 12], fill: "surface", stroke: "control", radius: "md", cross: o.h ? "MIN" : "CENTER", h: o.h || 40 });
  add(f, input, { fillW: true });
  await addText(input, value, o.placeholder ? "Body/Default" : "Body/Default", o.placeholder ? "muted" : "ink");
  return f;
}
async function bullets(parent, items, style = "Body/Small", color = "ink-2") { for (const t of items) await addText(parent, "• " + t, style, color, { wrap: true }); }
function frameMock(name, w, h, boxes = [], rounded = true) {
  const f = figma.createFrame(); f.name = name; f.resize(w, h); f.clipsContent = true; if (rounded) radius(f, "lg"); fill(f, "stage");
  for (const [x, y, bw, bh, col, dash] of boxes) {
    const person = figma.createRectangle(); person.resize(bw * 0.8, bh * 0.85); person.x = x + bw * 0.1; person.y = y + bh * 0.15; person.cornerRadius = 24;
    person.fills = [{ type: "SOLID", color: rgb("#55607A") }]; f.appendChild(person);
    const b = figma.createRectangle(); b.resize(bw, bh); b.x = x; b.y = y; b.fills = []; stroke(b, col, 3, dash); f.appendChild(b);
  }
  return f;
}

async function screens(page) {
  const out = [];

  // 1 Describe
  {
    const f = await shell(0, "What should your camera detect?", "Describe it in your own words. We turn it into a detection task you can check before anything is trained.");
    f.counterAxisAlignItems = "CENTER";
    const c = card("Prompt composer", { w: 690 });
    add(f, c);
    await addText(c, "Find people without safety goggles at the lab bench", "Body/Default", "ink");
    const attachments = box("Attachments and submit", "HORIZONTAL", { gap: 10, cross: "CENTER" });
    add(c, attachments, { fillW: true });
    attachments.appendChild(inst("Button", "Style=Secondary, State=Default", { Label: "+ Attach footage" }));
    await addText(attachments, "lab-bench.mp4", "Body/Small", "muted");
    spacer(attachments);
    const next = inst("Button", "Style=Primary, State=Default", { Label: "Create task" });
    attachments.appendChild(next);
    out.push([f, next]);
  }

  // 2 Upload
  {
    const f = await shell(1, "Upload footage from your camera", "Use footage from the place where the camera will actually run. A few minutes is enough: we pick about 40 varied frames.");
    f.counterAxisAlignItems = "CENTER";
    const c = card("Footage composer", { w: 690 });
    add(f, c);
    await addText(c, "+ Attach images or video", "Body/Strong", "ink");
    await addText(c, "lab-bench.mp4  ×", "Body/Small", "muted");
    const next = actions(c, [["← Change the task", "Secondary"]], [["Upload and label", "Primary"]]);
    out.push([f, next]);
  }

  // 3 Prepare
  {
    const f = await shell(2, "Check the automatic labels", "An open-vocabulary detector labelled every frame from your description. Fix anything wrong: these labels are what the model learns from.");
    const [main, aside] = cols(f);
    const c = card("Annotator"); add(main, c, { fillW: true });
    const hr = box("Frame header", "HORIZONTAL", { gap: 8, cross: "CENTER" }); add(c, hr, { fillW: true });
    hr.appendChild(await text("session_1_frame_004.jpg", "Body/Small Strong", "ink")); hr.appendChild(await text("frame 4 of 36", "Body/Small", "muted"));
    spacer(hr); hr.appendChild(inst("Button", "Style=Secondary, State=Default", { Label: "←" })); hr.appendChild(inst("Button", "Style=Secondary, State=Default", { Label: "→" }));
    const img = frameMock("Frame preview", 820, 460, [[120, 120, 150, 300, "brand"], [460, 110, 150, 300, "error", [10, 8]]]);
    add(c, img, { fillW: true });
    const list = box("Boxes", "VERTICAL", { gap: 4 }); add(c, list, { fillW: true });
    const r1 = box("Box 1", "HORIZONTAL", { gap: 8, cross: "CENTER", pad: [4, 8, 4, 8], fill: "brand-soft", radius: "md" }); add(list, r1, { fillW: true });
    r1.appendChild(inst("Chip", "Tone=Default", { Label: "Box 1: no_goggles" })); r1.appendChild(await text("auto, 89% sure", "Body/Small", "muted")); spacer(r1);
    r1.appendChild(inst("Button", "Style=Secondary, State=Default", { Label: "✓ Correct" })); r1.appendChild(inst("Button", "Style=Danger, State=Default", { Label: "Delete" }));
    const r2 = box("Box 2", "HORIZONTAL", { gap: 8, cross: "CENTER", pad: [4, 8, 4, 8] }); add(list, r2, { fillW: true });
    r2.appendChild(inst("Chip", "Tone=Default", { Label: "Box 2: goggles" })); r2.appendChild(await text("auto, 41% sure (unsure)", "Body/Small", "muted"));
    await addText(c, "Drag on the image to add a box · select a box to fix or delete it · dashed = the auto-labeller was unsure", "Caption", "muted", { wrap: true });
    const d = card("Dataset"); add(aside, d, { fillW: true });
    await addText(d, "Dataset", "Body/Strong", "ink");
    await addText(d, "36 frames · 31 boxes · 1 checked by you\nno_goggles: 17 · goggles: 14\nRecording: session_1", "Body/Small", "ink-2", { wrap: true });
    const next = inst("Button", "Style=Primary, State=Default", { Label: "Continue to training →" }); add(d, next, { fillW: true });
    add(d, inst("Button", "Style=Secondary, State=Default", { Label: "Save corrections" }), { fillW: true });
    out.push([f, next]);
  }

  // 4 Train
  {
    const f = await shell(3, "Train a small, fast model", "We fine-tune a compact detector on your labelled frames. It runs on a GPU and takes a few minutes.");
    const c = card("Training options", { gap: 24 }); add(f, c, { fillW: true });
    const g = box("Options", "HORIZONTAL", { gap: 24 }); add(c, g, { fillW: true });
    const l = box("What to train", "VERTICAL", { gap: 8 }); add(g, l, { grow: true }); l.layoutSizingHorizontal = "FILL";
    await addText(l, "What to train", "Body/Strong", "ink");
    for (const t of ["☑  Trained · real footage only · 29 train, 7 val", "☑  Trained · real + synthetic · 29 train, 7 val, 24 synthetic", "☑  Zero-shot baseline · the large open-vocabulary model without training"]) await addText(l, t, "Body/Small", "ink", { wrap: true });
    const r = box("Training time", "VERTICAL", { gap: 8 }); add(g, r, { grow: true }); r.layoutSizingHorizontal = "FILL";
    await addText(r, "Training time", "Body/Strong", "ink");
    const seg = box("Presets", "HORIZONTAL", { gap: 4, pad: [4, 4, 4, 4], fill: "surface-2", radius: "md" }); r.appendChild(seg);
    for (const [t, on] of [["Quick · about 1 min", false], ["Standard · about 3 min", true], ["Thorough · about 6 min", false]]) {
      const o = box(t, "HORIZONTAL", { pad: [6, 12, 6, 12], fill: on ? "surface" : null, radius: "sm", stroke: on ? "line" : null }); seg.appendChild(o);
      o.appendChild(await text(t, "Body/Small Strong", on ? "ink" : "ink-2"));
    }
    await addText(r, "▸ Advanced settings", "Body/Small", "ink-2");
    const next = actions(c, [["← Back", "Secondary"]], [["Train again", "Secondary"], ["Verify on new footage →", "Primary"]]);
    const p = card("Progress"); add(f, p, { fillW: true });
    await addText(p, "Progress", "Heading/H3", "ink");
    for (const [name, status, done] of [["Trained · real footage only", "✓ succeeded", 1], ["Trained · real + synthetic", "✓ succeeded", 1]]) {
      const row = box(name, "HORIZONTAL", { gap: 8, cross: "CENTER" }); add(p, row, { fillW: true });
      row.appendChild(await text(name, "Body/Small Strong", "ink")); row.appendChild(inst("Badge", "Tone=Success", { Label: status }));
      row.appendChild(await text("done in 10s (sample)", "Body/Small", "muted")); spacer(row);
      row.appendChild(await text("validation recall 90%, precision 91%", "Caption", "muted"));
      const bar = box("Progress bar", "HORIZONTAL", { fill: "surface-2", radius: "full", h: 8 }); add(p, bar, { fillW: true }); bar.cornerRadius = 4;
      const fillBar = rect("Value", 10, 8, "brand"); fillBar.cornerRadius = 4; add(bar, fillBar, { grow: done === 1 });
    }
    await addText(p, "Validation numbers come from frames of the same recording. They help pick a model but are optimistic. The real score comes from the next step.", "Caption", "muted", { wrap: true });
    out.push([f, next]);
  }

  // 5 Verify
  {
    const f = await shell(4, "Verify on footage the model has never seen", "Record a few minutes at another time of day or from another angle. This independent test is the score that counts.");
    add(f, inst("Banner", "Tone=Sample", { Title: "Sample results", Body: "Produced by the real evaluation engine on simulated predictions. They are not measurements of your model." }), { fillW: true });
    const t = card("Model comparison"); add(f, t, { fillW: true });
    const th = box("Header", "HORIZONTAL", { gap: 8, cross: "CENTER" }); add(t, th, { fillW: true });
    th.appendChild(await text("Model comparison on independent test footage", "Heading/H3", "ink")); th.appendChild(inst("Badge", "Tone=Sample", { Label: "Sample data" }));
    const W = [300, 130, 130, 110, 110, 90, 110];
    const rowOf = async (cells, o = {}) => {
      const r = box("Row", "HORIZONTAL", { gap: 0, cross: "CENTER", pad: [12, 8, 12, 8], fill: o.sel ? "brand-soft" : null }); add(t, r, { fillW: true });
      for (let i = 0; i < cells.length; i++) {
        const cell = box("Cell", "HORIZONTAL", { w: W[i] || 120 }); r.appendChild(cell);
        if (typeof cells[i] === "string") cell.appendChild(await text(cells[i], o.head ? "Label" : i === 0 ? "Body/Small Strong" : "Body/Small", o.head ? "muted" : "ink"));
        else cell.appendChild(cells[i]);
      }
    };
    await rowOf(["Model", "Recall", "Precision", "F1", "False alarms", "Missed", "Verdict"], { head: true });
    await rowOf(["Zero-shot baseline (no training)", "49%", "54%", "51%", "35", "43", inst("Badge", "Tone=Error", { Label: "Not ready" })]);
    await rowOf(["Trained · real footage only", "90%  +42 pts", "87%  +33 pts", "89%", "11", "8", inst("Badge", "Tone=Success", { Label: "Ready" })], { sel: true });
    await rowOf(["Trained · real + synthetic", "83%  +35 pts", "93%  +39 pts", "88%", "5", "14", inst("Badge", "Tone=Success", { Label: "Ready" })]);
    add(t, inst("Banner", "Tone=Warning", { Title: "Synthetic A/B test", Body: "Synthetic data did NOT improve results on real footage. The real-only model is the safer choice. F1: real-only 88.9% vs real + synthetic 88.0%." }), { fillW: true });

    const rc = card("Model report card"); add(f, rc, { fillW: true });
    const rh = box("Header", "HORIZONTAL", { gap: 8, cross: "CENTER" }); add(rc, rh, { fillW: true });
    rh.appendChild(await text("Model report card", "Heading/H3", "ink")); rh.appendChild(inst("Badge", "Tone=Sample", { Label: "Sample data" })); spacer(rh);
    rh.appendChild(inst("Button", "Style=Secondary, State=Default", { Label: "Download JSON" }));
    await addText(rc, "Trained · real footage only · base yolo11n.pt · version model_sample_real · tested on ds_sample_test (test split)", "Caption", "muted", { wrap: true });
    add(rc, inst("Verdict", "Verdict=Ready", {}), { fillW: true });
    const kpis = box("KPIs", "HORIZONTAL", { gap: 12 }); add(rc, kpis, { fillW: true });
    for (const [l, v, r] of [["Recall · objects found", "90%", "95% range 82%–95%"], ["Precision · alerts that are real", "87%", "95% range 79%–93%"], ["F1 · balance", "89%", "Balances precision and recall"], ["Speed", "212 FPS", "4.7 ms per frame on the backend GPU"]]) {
      const k = inst("KPI", "", { Label: l, Value: v, Range: r }); add(kpis, k, { grow: true });
    }
    await addText(rc, "Test data and limitations", "Body/Strong", "ink");
    await addText(rc, "48 independent frames (4 with nothing to detect) from 2 recording sessions never used for training. Box counted correct at overlap ≥ 0.5, confidence ≥ 0.25. A small test set shows how the model behaves here; it does not prove production safety.", "Body/Small", "ink-2", { wrap: true });

    const gal = card("Failure gallery"); add(f, gal, { fillW: true });
    await addText(gal, "Failure gallery", "Heading/H3", "ink");
    await addText(gal, "Real test frames the model got wrong, with the likely cause and what to do about it.", "Body/Small", "ink-2", { wrap: true });
    const tiles = box("Tiles", "HORIZONTAL", { gap: 12 }); add(gal, tiles, { fillW: true });
    for (const [kind, cls, reason, fix] of [["Missed", "goggles", "Not detected at all", "Capture more footage in this condition."], ["Missed", "no_goggles", "Seen, but not confident enough", "Add similar examples."], ["False alarm", "goggles", "False alarm on the background", "Add empty scenes and look-alikes."], ["False alarm", "no_goggles", "Confused with another class", "Add examples of both classes."]]) {
      const tile = box(kind, "VERTICAL", { fill: "surface", stroke: "line", radius: "lg" }); add(tiles, tile, { grow: true }); tile.clipsContent = true;
      const im = frameMock("Frame", 270, 150, [[90, 30, 70, 110, kind === "Missed" ? "fn" : "fp", kind === "Missed" ? null : [8, 6]]], false);
      add(tile, im, { fillW: true });
      const meta = box("Meta", "VERTICAL", { gap: 4, pad: [12, 12, 12, 12] }); add(tile, meta, { fillW: true });
      const mh = box("Kind", "HORIZONTAL", { gap: 8, cross: "CENTER" }); add(meta, mh, { fillW: true });
      mh.appendChild(inst("Badge", kind === "Missed" ? "Tone=Warning" : "Tone=Error", { Label: kind })); mh.appendChild(await text(cls, "Body/Small Strong", "ink"));
      await addText(meta, reason, "Body/Small", "ink", { wrap: true });
      await addText(meta, "→ " + fix, "Caption", "muted", { wrap: true });
    }
    out.push([f, actions(f, [["← Back", "Secondary"]], [["Deploy this model →", "Primary"]])]);
  }

  // Deploy · DashboardSpec example
  {
    const f = await shell(5, "Detect missing safety goggles in the lab", "Review the latest detections from your lab camera.");
    const [main, aside] = cols(f, 340);
    const camera = card("Camera preview");
    add(main, camera, { fillW: true });
    await addText(camera, "Lab camera", "Heading/H3", "ink");
    add(camera, frameMock("Sample inference frame", 760, 410, [[170, 90, 170, 260, "brand"]]), { fillW: true });
    const latest = card("Detection table");
    add(main, latest, { fillW: true });
    await addText(latest, "Latest detections", "Heading/H3", "ink");
    await addText(latest, "Safety goggles missing                    92% confidence", "Body/Small", "ink-2");
    const count = card("KPI");
    add(aside, count, { fillW: true });
    await addText(count, "Goggles missing in this frame", "Heading/H3", "ink");
    await addText(count, "1", "Heading/H1", "brand-ink");
    const trend = card("Time series");
    add(aside, trend, { fillW: true });
    await addText(trend, "Detections over time", "Heading/H3", "ink");
    await addText(trend, "Waiting for more inference frames", "Body/Small", "muted");
    const distribution = card("Class distribution");
    add(aside, distribution, { fillW: true });
    await addText(distribution, "Detections by class", "Heading/H3", "ink");
    await addText(distribution, "Safety goggles missing · 1", "Body/Small", "ink-2");
    const tools = box("Inference and export", "HORIZONTAL", { gap: 12 });
    add(f, tools, { fillW: true });
    tools.appendChild(inst("Button", "Style=Primary, State=Default", { Label: "Run sample inference" }));
    tools.appendChild(inst("Button", "Style=Secondary, State=Default", { Label: "Export dashboard" }));
    tools.appendChild(inst("Badge", "Tone=Sample", { Label: "Simulated sample data" }));
    const refine = card("Dashboard refinement", { w: 700 });
    add(f, refine);
    await field(refine, "Refine dashboard", "Put the detection table first");
    refine.appendChild(inst("Button", "Style=Secondary, State=Default", { Label: "Apply" }));
    out.push([f, null]);
  }

  // place screens left-to-right and wire the prototype (primary action -> next screen)
  let x = 0;
  for (const [f] of out) { page.appendChild(f); f.x = x; f.y = 0; x += f.width + 160; }
  for (let i = 0; i < out.length - 1; i++) {
    const [, btn] = out[i];
    if (!btn) continue;
    try {
      await btn.setReactionsAsync([{ trigger: { type: "ON_CLICK" }, actions: [{ type: "NODE", destinationId: out[i + 1][0].id, navigation: "NAVIGATE", transition: { type: "SMART_ANIMATE", easing: { type: "EASE_OUT" }, duration: 0.25 }, preserveScrollPosition: false }] }]);
    } catch (e) { /* prototype links are optional */ }
  }
  try { page.flowStartingPoints = [{ nodeId: out[0][0].id, name: "ZALU journey" }]; } catch (e) { /* optional */ }
  return out.map(([f]) => f);
}

// ---------------------------------------------------------------- main
const PAGE_NAMES = ["Cover & Foundations", "Components", "Journey"];
async function pageNamed(name) {
  let p = figma.root.children.find((x) => x.name === name);
  if (!p) {
    // Starter plan allows 3 pages: create if possible, otherwise take over a page that is not one of ours
    p = figma.root.children.length < 3 ? figma.createPage() : figma.root.children.find((x) => !PAGE_NAMES.includes(x.name));
    if (!p) throw new Error("No free page: rename or delete a page and run again");
    p.name = name;
  }
  await p.loadAsync();
  return p;
}
function clear(page) {
  for (const n of [...page.children]) {
    const ours = n.name.startsWith(PREFIX) || ["Button", "Badge", "Banner", "Step", "Verdict", "Chip", "KPI", "Components"].includes(n.name) ||
      (n.type === "TEXT" && ["Button", "Badge", "Banner", "Step", "Verdict", "Chip", "KPI", "Components"].includes(n.name)) ||
      (n.type === "TEXT" && n.name.startsWith("Every component mirrors"));
    if (ours) n.remove();
  }
}

(async () => {
  let stage = "start";
  const say = (msg) => { try { figma.notify(msg, { timeout: 2000 }); } catch (e) { /* notify is optional */ } };
  try {
    stage = "1/5 tokens and text styles"; say("ZALU: " + stage);
    await foundations();
    stage = "2/5 pages";
    const pFound = await pageNamed("Cover & Foundations");
    const pComp = await pageNamed("Components");
    const pJourney = await pageNamed("Journey");

    stage = "3/5 Cover & Foundations page"; say("ZALU: " + stage);
    await figma.setCurrentPageAsync(pFound); clear(pFound);
    await foundationsPage(pFound);

    stage = "4/5 Components page"; say("ZALU: " + stage);
    await figma.setCurrentPageAsync(pComp); clear(pComp);
    await components(pComp);

    stage = "5/5 Journey screens"; say("ZALU: " + stage);
    await figma.setCurrentPageAsync(pJourney); clear(pJourney);
    const frames = await screens(pJourney);
    figma.viewport.scrollAndZoomIntoView(frames);
    figma.closePlugin(`✓ ZALU: ${Object.keys(V).length} variables, ${Object.keys(S).length} text styles, ${Object.keys(C).length} components, ${frames.length} screens.`);
  } catch (e) {
    // keep a window open with the exact failing step so it can be copied and reported
    const msg = `Step: ${stage}\n${e && e.message ? e.message : e}\n\n${(e && e.stack) || ""}`;
    const esc = msg.replace(/&/g, "&amp;").replace(/</g, "&lt;");
    figma.showUI(`<div style="font:12px Inter,system-ui,sans-serif;padding:12px"><b style="color:#A3303D">ZALU builder failed</b>
      <p>Copy this text and send it to the developer:</p><textarea style="width:100%;height:170px;font:11px monospace" readonly>${esc}</textarea></div>`,
      { width: 420, height: 280, title: "ZALU builder" });
  }
})();
